import pandas as pd, statistics, os, re, csv

snapshots_dir = 'data/snapshots'

def load_wide_prices(path):
    prices = {}
    with open(path, newline='', encoding='utf-8-sig') as f:
        reader = csv.reader(f)
        headers = next(reader)
        tickers = headers[1:]
        for row in reader:
            date = row[0]
            for i, ticker in enumerate(tickers):
                if i + 1 < len(row) and row[i+1].strip():
                    try:
                        prices.setdefault(ticker, {})[date] = float(row[i+1])
                    except ValueError:
                        pass
    return prices

def get_fwd_ret(prices, ticker, anchor_date, n, all_dates):
    ticker_prices = prices.get(ticker, {})
    # find anchor
    if anchor_date in ticker_prices:
        p0 = ticker_prices[anchor_date]
        ad = anchor_date
    else:
        bd = [d for d in all_dates if d <= anchor_date and d in ticker_prices]
        if not bd:
            return None
        ad = bd[-1]
        p0 = ticker_prices[ad]
    # find forward
    try:
        idx = all_dates.index(ad)
    except ValueError:
        return None
    target = idx + n
    if target >= len(all_dates):
        return None
    td = all_dates[target]
    p1 = ticker_prices.get(td)
    if p1 is not None and p0 > 0:
        return (p1 - p0) / p0
    return None

up = load_wide_prices('data/universe_prices.csv')
ip = load_wide_prices('data/indices_prices.csv')
all_dates_up = sorted(set().union(*[set(d.keys()) for d in up.values()]))

canonical_era1 = sorted([d for d in os.listdir(snapshots_dir) 
                          if re.match(r'^20\d\d-\d\d-\d\d$', d) 
                          and '2024-10-18' <= d <= '2026-01-15'])

era1_results = {1: [], 5: [], 20: [], 60: []}
for snap_date in canonical_era1:
    path = os.path.join(snapshots_dir, snap_date, 'rankings.csv')
    if not os.path.exists(path):
        continue
    with open(path, newline='', encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        rows = list(reader)
    if not rows:
        continue
    rank_col = next((c for c in ['actionable_rank','rank','final_rank'] if c in rows[0]), None)
    if not rank_col:
        continue
    ranked = []
    for r in rows:
        try:
            ranked.append((float(r[rank_col]), r['ticker']))
        except (ValueError, TypeError):
            pass
    ranked.sort()
    top30 = [t for _, t in ranked[:30]]

    for n in [1, 5, 20, 60]:
        port_rets = [get_fwd_ret(up, t, snap_date, n, all_dates_up) for t in top30]
        port_rets = [r for r in port_rets if r is not None]
        xbi_r = get_fwd_ret(ip, 'XBI', snap_date, n, all_dates_up)
        if len(port_rets) >= 28 and xbi_r is not None:
            era1_results[n].append((statistics.mean(port_rets), xbi_r))

print("Era1 (2024-10-18 to 2026-01-15) stats:")
for n in [1, 5, 20, 60]:
    data = era1_results[n]
    if not data:
        continue
    ports, xbis = zip(*data)
    avg_e = statistics.mean(p - x for p, x in data)
    med_e = statistics.median(p - x for p, x in data)
    hr = sum(1 for p, x in data if p > x) / len(data)
    print(f"  {n}d: n={len(data)}, avg_port={statistics.mean(ports)*100:.2f}%, avg_xbi={statistics.mean(xbis)*100:.2f}%, avg_excess={avg_e*100:.2f}%, med_excess={med_e*100:.2f}%, hit_rate={hr:.1%}")
