# universe_prices only has 307 of the ~350 universe tickers, so many top-30 tickers may be missing
# The prior backtest got 59 snaps. Let me use threshold of 15 (50%) to capture these snaps
import pandas as pd, statistics, csv, os, re

snapshots_dir = 'data/snapshots'
up = {}
with open('data/universe_prices.csv', newline='', encoding='utf-8-sig') as f:
    reader = csv.reader(f)
    headers = next(reader)
    tickers = headers[1:]
    for row in reader:
        date = row[0]
        for i, ticker in enumerate(tickers):
            if i + 1 < len(row) and row[i+1].strip():
                try:
                    up.setdefault(ticker, {})[date] = float(row[i+1])
                except ValueError:
                    pass

ip = {}
with open('data/indices_prices.csv', newline='', encoding='utf-8-sig') as f:
    reader = csv.reader(f)
    headers = next(reader)
    tickers2 = headers[1:]
    for row in reader:
        date = row[0]
        for i, ticker in enumerate(tickers2):
            if i + 1 < len(row) and row[i+1].strip():
                try:
                    ip.setdefault(ticker, {})[date] = float(row[i+1])
                except ValueError:
                    pass

all_dates = sorted(set().union(*[set(d.keys()) for d in up.values()]))

canonical_era1 = sorted([d for d in os.listdir(snapshots_dir)
                          if re.match(r'^20\d\d-\d\d-\d\d$', d)
                          and '2024-10-18' <= d <= '2026-01-15'])

era1_data = {1: [], 5: [], 20: [], 60: []}
for snap_date in canonical_era1:
    path = os.path.join(snapshots_dir, snap_date, 'rankings.csv')
    if not os.path.exists(path):
        continue
    df = pd.read_csv(path)
    if 'actionable_rank' not in df.columns:
        continue
    top30 = df.nsmallest(30, 'actionable_rank')['ticker'].tolist()

    for n in [1, 5, 20, 60]:
        rets = []
        for t in top30:
            tp = up.get(t, {})
            ad = snap_date if snap_date in tp else None
            if ad is None:
                before = [d for d in all_dates if d <= snap_date and d in tp]
                if before: ad = before[-1]
            if ad is None:
                continue
            p0 = tp[ad]
            try:
                idx = all_dates.index(ad)
            except ValueError:
                continue
            fwd_idx = idx + n
            if fwd_idx >= len(all_dates):
                continue
            fwd_date = all_dates[fwd_idx]
            p1 = tp.get(fwd_date)
            if p1 is not None and p0 > 0:
                rets.append((p1 - p0) / p0)

        xbi_p = ip.get('XBI', {})
        xbi_ad = snap_date if snap_date in xbi_p else max((d for d in all_dates if d <= snap_date and d in xbi_p), default=None)
        if xbi_ad is None:
            continue
        try:
            xbi_idx = all_dates.index(xbi_ad)
        except ValueError:
            continue
        xbi_fwd_idx = xbi_idx + n
        if xbi_fwd_idx >= len(all_dates):
            continue
        xbi_fwd = all_dates[xbi_fwd_idx]
        xbi_r = (xbi_p[xbi_fwd] - xbi_p[xbi_ad]) / xbi_p[xbi_ad]

        # Use threshold 15 (50%) instead of 28
        if len(rets) >= 15:
            era1_data[n].append((statistics.mean(rets), xbi_r))

print("Era1 stats (threshold=15 valid tickers):")
for n in [1, 5, 20, 60]:
    data = era1_data[n]
    if not data:
        print(f"  {n}d: no data")
        continue
    ports, xbis = zip(*data)
    avg_e = statistics.mean(p - x for p, x in data)
    med_e = statistics.median(p - x for p, x in data)
    hr = sum(1 for p, x in data if p > x) / len(data)
    print(f"  {n}d: n={len(data)}, avg_port={statistics.mean(ports)*100:.2f}%, avg_xbi={statistics.mean(xbis)*100:.2f}%, avg_excess={avg_e*100:.2f}%, med_excess={med_e*100:.2f}%, hit_rate={hr:.1%}")
